recipes.code:
{
  "inputs": [
    {
      "id": "chronary-api-key",
      "type": "promptString",
      "description": "Chronary API key - org key (chr_sk_...) or agent-scoped key (chr_ak_...). Request access at https://chronary.ai.",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@chronary/mcp@1.5.2"
      ],
      "env": {
        "CHRONARY_API_KEY": "${input:chronary-api-key}"
      }
    }
  }
}
